const $ = id => document.getElementById(id);
const pick = a => a[Math.floor(Math.random() * a.length)];

// ---------- Built-in photos (embedded in the page) and their default captions ----------
const BUILTIN = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const BUILTIN_CAPS = ['Yaadein 💛', 'Smiles ✨', 'Pyaari si shaam 🌇', 'Hasi wale pal 😊', 'Tour ki yaad 🌿',
  'Sunehri pal 🌅', 'Saath saath 💕', 'Ek khaas din 🎉', 'Chhoti si khushi 🌼', 'Hamesha ke liye 💫'];

// ---------- Local storage (per device: badges, card progress, offline fallback) ----------
const local = {
  get(k, d) { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch (e) { return d; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
};
let flags = local.get('mdn-flags', { loved: 0, game: false, gift: false, spin: false, unlocked: [] });
const saveFlags = () => local.set('mdn-flags', flags);

// ---------- Shared state (shared through db + assets when available) ----------
const DEFAULT_NOTES = [
  { text: 'Aap ka din bahut accha jaaye ✨', color: '#fff3b0' },
  { text: 'Yahan kuch bhi likho… ✏️', color: '#ffd6e0' }
];
let state = local.get('mdn-state', null) || { name: '', notes: DEFAULT_NOTES, photos: [], caps: {}, hidden: [] };
normalizeState(state);
function normalizeState(s) {
  s.name = s.name || ''; s.notes = Array.isArray(s.notes) ? s.notes : DEFAULT_NOTES;
  s.photos = Array.isArray(s.photos) ? s.photos : [];
  s.caps = s.caps && typeof s.caps === 'object' ? s.caps : {};
  s.hidden = Array.isArray(s.hidden) ? s.hidden : [];
  if (!s.photos.length) {
    const old = local.get('mdn-photos', null);
    if (old && old.length) s.photos = old.map(p => ({ src: p.src }));
  }
  return s;
}

let dbDoc = null, assetsApi = null, usingDb = false, canWrite = false, hasUserApi = false;
let saveTimer = null, writing = false, queued = false, rerenderLater = false;

// ---------- Owner mode (editing is locked by default) ----------
// Change this PIN to whatever you like. Triple-tap the "19 November" badge to unlock.
const OWNER_PIN = '1911';
const OWNER_KEY = 'mdn-owner';
let ownerUnlocked = local.get(OWNER_KEY, false) === true;

function isReadOnly() {
  const params = new URLSearchParams(location.search);
  if (params.get('view') === '1') return true;      // explicit share link
  if (hasUserApi) return !canWrite;                 // platform permissions decide
  if (ownerUnlocked) return false;                  // unlocked on this device
  if (location.protocol === 'file:') return false;  // author's own machine
  return true;                                      // everyone else: view only
}

function persistLocal() { local.set('mdn-state', state); }
function persist() {
  persistLocal();
  if (isReadOnly() || !usingDb) return;
  clearTimeout(saveTimer);
  saveTimer = setTimeout(flushSave, 500);
}
async function flushSave() {
  if (isReadOnly()) return;
  if (writing) { queued = true; return; }
  writing = true;
  try { await dbDoc.set(JSON.parse(JSON.stringify(state))); }
  catch (e) { toast('Save nahi hua, phir se try karo'); }
  writing = false;
  if (queued) { queued = false; flushSave(); }
}

// ---------- Toast ----------
let tt, undoFn = null;
function toast(msg, undo) {
  $('toastMsg').textContent = msg;
  undoFn = undo || null;
  $('toastBtn').hidden = !undo;
  $('toast').classList.add('show');
  clearTimeout(tt); tt = setTimeout(() => $('toast').classList.remove('show'), 3500);
}
$('toastBtn').addEventListener('click', () => { if (undoFn) undoFn(); $('toast').classList.remove('show'); });

// ---------- Bubble & confetti ----------
let bt;
function say(msg, el) {
  const b = $('bubble'); b.textContent = msg;
  const r = el.getBoundingClientRect();
  b.style.left = Math.min(Math.max(10, r.left - 20), innerWidth - 250) + 'px';
  b.style.top = Math.max(10, r.top - 56) + 'px';
  b.classList.add('show'); clearTimeout(bt); bt = setTimeout(() => b.classList.remove('show'), 2400);
}
function confetti(x, y, n = 14) {
  const e = ['💖','⭐','✨','🎉','💛','🎈','💙'];
  for (let i = 0; i < n; i++) {
    const s = document.createElement('span'); s.className = 'bit'; s.textContent = pick(e);
    s.style.left = x + 'px'; s.style.top = y + 'px';
    s.style.setProperty('--dx', (Math.random() * 220 - 110) + 'px');
    s.style.setProperty('--dy', (Math.random() * -180 - 30) + 'px');
    s.style.setProperty('--rot', (Math.random() * 720 - 360) + 'deg');
    document.body.appendChild(s); setTimeout(() => s.remove(), 1000);
  }
}

// ---------- Stickers & doodles ----------
const lines = ["Aap ki smile sabse cute hai 😊", "Sparkle sparkle ✨", "Virtual high-five ✋", "You're a legend 🏅"];
document.querySelectorAll('.sticker, .doodles button').forEach(b => b.addEventListener('click', () => {
  b.classList.remove('pop'); void b.offsetWidth; b.classList.add('pop');
  const r = b.getBoundingClientRect(); confetti(r.left + r.width / 2, r.top + r.height / 2, 8);
  say(b.dataset.msg || pick(lines), b);
}));

