function openTab(id) {
  document.querySelectorAll('.tab').forEach(x => x.classList.toggle('on', x.dataset.tab === id));
  document.querySelectorAll('.panel').forEach(p => p.classList.toggle('active', p.id === id));
  if (id === 'p-home') renderBadges();
}
document.querySelectorAll('.tab').forEach(t => t.addEventListener('click', () => openTab(t.dataset.tab)));

// Deep link: ?tab=p-photos (etc.)
