// Triple-tap the badge on the header to open the owner unlock box
let badgeTaps = 0, badgeTimer = null;
document.querySelector('header .badge').addEventListener('click', () => {
  badgeTaps++; clearTimeout(badgeTimer);
  badgeTimer = setTimeout(() => { badgeTaps = 0; }, 900);
  if (badgeTaps < 3) return;
  badgeTaps = 0;
  if (ownerUnlocked && !hasUserApi) {          // lock this device again
    ownerUnlocked = false; local.set(OWNER_KEY, false);
    applyPermissions(); toast('Lock ho gaya 🔒');
    return;
  }
  if (!isReadOnly()) return;                   // already an editor here
  openLock();
});
function openLock() {
  $('lockbox').classList.remove('hidden');
  $('lockPin').value = '';
  setTimeout(() => $('lockPin').focus(), 50);
}
function closeLock() { $('lockbox').classList.add('hidden'); }
function tryUnlock() {
  if ($('lockPin').value.trim() !== OWNER_PIN) {
    toast('Galat PIN 🔒'); $('lockPin').select(); return;
  }
  ownerUnlocked = true; local.set(OWNER_KEY, true); closeLock();
  applyPermissions();
  toast(isReadOnly() ? 'PIN sahi hai, par ye link view-only hai' : 'Owner mode 🔓 ab edit kar sakte ho');
}
$('lockGo').addEventListener('click', tryUnlock);
$('lockCancel').addEventListener('click', closeLock);
$('lockPin').addEventListener('keydown', e => { if (e.key === 'Enter') tryUnlock(); });
$('lockbox').addEventListener('click', e => { if (e.target === $('lockbox')) closeLock(); });

