const badgeDefs = [
  { id: 'cards', ic: '💌', name: 'Card Lover',      test: () => flags.loved >= 3 },
  { id: 'notes', ic: '📝', name: 'Note Writer',     test: () => state.notes.some(n => n.text && n.text.trim()) },
  { id: 'photo', ic: '📸', name: 'Memory Keeper',   test: () => getPhotoItems().length > 0 },
  { id: 'game',  ic: '🎮', name: 'Gamer',           test: () => flags.game },
  { id: 'gift',  ic: '🎁', name: 'Surprise Hunter', test: () => flags.gift },
  { id: 'spin',  ic: '✨', name: 'Compliment Fan',  test: () => flags.spin }
];
function renderBadges() {
  const box = $('badges'); box.innerHTML = '';
  let got = 0;
  badgeDefs.forEach(b => {
    const on = b.test();
    if (on) got++;
    if (on && !flags.unlocked.includes(b.id)) {
      flags.unlocked.push(b.id); saveFlags();
      toast(`🏅 Badge unlocked: ${b.name}!`);
      confetti(innerWidth / 2, innerHeight / 3, 16);
    }
    const c = document.createElement('div');
    c.className = 'chip' + (on ? ' on' : '');
    c.innerHTML = `<span class="ic">${b.ic}</span>${b.name}`;
    box.appendChild(c);
  });
  $('progress').textContent = `Badges: ${got} / ${badgeDefs.length} 🏅`;
}

// ---------- Cards: swipe stack (personal, per device) ----------
const cards = [
  { emo:'💛', hi:'Aap ho toh sab aasan lagta hai', en:'With you, everything feels easier.', bg:'#fffdf8' },
  { emo:'😂', hi:'Aapki hasi = best medicine', en:'Your laugh is the best medicine.', bg:'#fff3b0' },
  { emo:'🛡️', hi:'Mushkil mein bhi aap strong ho', en:'Even on hard days, you stand strong.', bg:'#c9f2e0' },
  { emo:'🤗', hi:'Aapka hug, poori duniya ke barabar', en:'One hug from you feels like the world.', bg:'#cfe8ff' },
  { emo:'🙌', hi:'Aap jaise ho, bilkul perfect ho', en:'Just being you is more than enough.', bg:'#e3d4ff' },
  { emo:'🍕', hi:'Snack-buddy legend, obviously', en:'Certified legend of snacks.', bg:'#ffd6c2' }
];
let idx = 0, sessionLoved = 0, busy = false;
const stack = $('stack');
function renderStack() {
  stack.innerHTML = '';
  busy = false;
  if (idx >= cards.length) {
    stack.innerHTML = `<div class="done-msg">Sab dekh liye! 💖<br><button class="btn" id="replay" style="margin-top:14px;font-size:15px">Phir se dekho</button></div>`;
    $('replay').onclick = () => { idx = 0; sessionLoved = 0; renderStack(); };
    $('counter').textContent = `Loved ${sessionLoved} of ${cards.length} ❤️`;
    $('loveBtn').disabled = $('skipBtn').disabled = true;
    return;
  }
  $('loveBtn').disabled = $('skipBtn').disabled = false;
  cards.slice(idx, idx + 3).forEach((c, depth) => {
    const el = document.createElement('div');
    el.className = 'swipe';
    el.style.background = c.bg;
    el.style.zIndex = 10 - depth;
    el.style.transform = `translateY(${depth * 10}px) scale(${1 - depth * 0.04})`;
    el.dataset.depth = depth;
    el.innerHTML = `<div class="stamp love">LOVE 💖</div><div class="stamp skip">NEXT</div>
      <div class="emo">${c.emo}</div><div class="hi">${c.hi}</div><div class="en">${c.en}</div>`;
    if (depth === 0) attachDrag(el); else el.style.pointerEvents = 'none';
    stack.appendChild(el);
  });
  $('counter').textContent = `${idx + 1} / ${cards.length} · Loved ${sessionLoved} ❤️`;
}
function attachDrag(el) {
  let startX = 0, dx = 0, dragging = false;
  el.addEventListener('pointerdown', e => {
    if (busy) return;
    dragging = true; startX = e.clientX; dx = 0;
    el.setPointerCapture(e.pointerId); el.style.transition = 'none';
  });
  el.addEventListener('pointermove', e => {
    if (!dragging) return;
    dx = e.clientX - startX;
    el.style.transform = `translateX(${dx}px) rotate(${dx / 14}deg)`;
    el.querySelector('.love').style.opacity = Math.max(0, dx / 90);
    el.querySelector('.skip').style.opacity = Math.max(0, -dx / 90);
  });
  const release = () => {
    if (!dragging) return; dragging = false;
    if (Math.abs(dx) > 90) fly(el, dx > 0 ? 1 : -1);
    else {
      el.style.transition = 'transform .35s ease';
      el.style.transform = 'translateY(0) scale(1)';
      el.querySelector('.love').style.opacity = 0; el.querySelector('.skip').style.opacity = 0;
    }
  };
  el.addEventListener('pointerup', release);
  el.addEventListener('pointercancel', release);
}
function fly(el, dir) {
  if (busy) return; busy = true;
  if (dir > 0) {
    sessionLoved++; flags.loved++; saveFlags();
    const r = el.getBoundingClientRect(); confetti(r.left + r.width / 2, r.top + 40, 12);
    if (flags.loved === 3) renderBadges();
  }
  el.style.transition = 'transform .45s cubic-bezier(.5,0,.8,.4), opacity .45s ease';
  el.style.transform = `translate(${dir * 420}px, -60px) rotate(${dir * 35}deg) scale(.85)`;
  el.style.opacity = '0';
  setTimeout(() => { idx++; renderStack(); }, 430);
}
$('loveBtn').addEventListener('click', () => { const t = stack.querySelector('.swipe[data-depth="0"]'); if (t) fly(t, 1); });
$('skipBtn').addEventListener('click', () => { const t = stack.querySelector('.swipe[data-depth="0"]'); if (t) fly(t, -1); });

// ---------- Notes (shared) ----------
const noteColors = ['#fff3b0', '#ffd6e0', '#cfe8ff', '#c9f2e0', '#e3d4ff'];
function renderNotes() {
  const box = $('notes'); box.innerHTML = '';
  const ro = isReadOnly();
  state.notes.forEach((n, i) => {
    const d = document.createElement('div');
    d.className = 'note'; d.style.background = n.color;
    d.innerHTML = `${ro ? '' : '<button class="del" aria-label="Delete note">✕</button>'}<div class="body" contenteditable="${ro ? 'false' : 'true'}" spellcheck="false"></div>`;
    const body = d.querySelector('.body');
    const showPh = () => { if (!ro) body.innerHTML = '<span class="ph">Likho kuch…</span>'; };
    if (n.text) body.textContent = n.text; else showPh();
    if (!ro) {
      body.addEventListener('focus', () => { if (!n.text) body.textContent = ''; });
      body.addEventListener('input', () => { n.text = body.innerText; persist(); renderBadges(); });
      body.addEventListener('blur', () => { if (!n.text || !n.text.trim()) showPh(); rerenderFlush(); });
      d.querySelector('.del').addEventListener('click', () => {
        const removed = state.notes.splice(i, 1)[0]; persist(); renderNotes();
        toast('Note delete ho gaya', () => { state.notes.splice(i, 0, removed); persist(); renderNotes(); });
      });
    }
    box.appendChild(d);
  });
}
$('addNote').addEventListener('click', () => {
  if (isReadOnly()) return;
  state.notes.push({ text: '', color: pick(noteColors) }); persist(); renderNotes();
  const last = $('notes').lastElementChild; if (last) last.querySelector('.body').focus();
});

// ---------- Photos ----------
// Items: built-in photos first (unless hidden), then uploads. key = 'b0'.. for built-in, asset id or 'l0'.. for uploads.
const MAX_UPLOADS = 20;
function getPhotoItems() {
  const items = [];
  BUILTIN.forEach((src, i) => {
    const key = 'b' + i;
    if (state.hidden.includes(key)) return;
    items.push({ key, src, cap: state.caps[key] || BUILTIN_CAPS[i] || '', builtin: true });
  });
  state.photos.forEach((p, i) => {
    const key = p.id || ('l' + i);
    items.push({ key, src: p.id ? '/_blob/' + p.id : p.src, cap: state.caps[key] || '', id: p.id || null, legacyIndex: i, builtin: false });
  });
  return items;
}
function shrink(file) {
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onerror = reject;
    fr.onload = () => {
      const img = new Image();
      img.onerror = reject;
      img.onload = () => {
        const s = Math.min(1, 900 / Math.max(img.width, img.height));
        const c = document.createElement('canvas');
        c.width = Math.round(img.width * s); c.height = Math.round(img.height * s);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        c.toBlob(b => b ? resolve(b) : reject(new Error('blob')), 'image/jpeg', 0.8);
      };
      img.src = fr.result;
    };
    fr.readAsDataURL(file);
  });
}
function blobToDataURL(b) {
  return new Promise(res => { const fr = new FileReader(); fr.onload = () => res(fr.result); fr.readAsDataURL(b); });
}
async function addPhoto(file) {
  if (isReadOnly()) return;
  toast('Photo upload ho rahi hai… ⏳');
  try {
    const blob = await shrink(file);
    if (usingDb && assetsApi) {
      const a = await assetsApi.upload(blob);
      state.photos.push({ id: a.id });
    } else {
      state.photos.push({ src: await blobToDataURL(blob) });
    }
    persist(); renderPhotos(); renderBadges();
    toast('Photo add ho gayi 📸');
  } catch (e) {
    toast('Photo add nahi hui, dobara try karo');
  }
}
function renderPhotos() {
  const box = $('photos'); box.innerHTML = '';
  const ro = isReadOnly();
  const items = getPhotoItems();
  items.forEach((it, i) => {
    const d = document.createElement('div'); d.className = 'polaroid'; d.tabIndex = 0;
    d.setAttribute('role', 'button'); d.setAttribute('aria-label', 'Open photo');
    d.innerHTML = `${ro ? '' : '<button class="del" aria-label="Remove photo">✕</button>'}<img alt="" loading="lazy" src="${it.src}"><div class="cap"></div>`;
    d.querySelector('.cap').textContent = it.cap;
    d.addEventListener('click', e => { if (e.target.closest('.del')) return; openLb(i); });
    d.addEventListener('keydown', e => { if (e.key === 'Enter') openLb(i); });
    if (!ro) {
      const del = d.querySelector('.del');
      if (del) del.addEventListener('click', e => {
        e.stopPropagation();
        if (!confirm('Ye photo hatayein?')) return;
        removeItem(it);
      });
    }
    box.appendChild(d);
  });
  if (!ro && state.photos.length < MAX_UPLOADS) {
    const add = document.createElement('label'); add.className = 'addtile';
    add.innerHTML = `<span>+</span>Nayi photo<input type="file" accept="image/*" class="pick">`;
    add.querySelector('.pick').addEventListener('change', e => {
      const f = e.target.files[0]; e.target.value = '';
      if (f) addPhoto(f);
    });
    box.appendChild(add);
  }
  $('photoSub').textContent = `${items.length} yaadein · tap to open${ro ? ' · sirf dekh sakte ho' : ''}`;
}
function removeItem(it) {
  if (isReadOnly()) return;
  if (it.builtin) {
    state.hidden.push(it.key);
    toast('Photo chhupa di', () => { state.hidden = state.hidden.filter(k => k !== it.key); persist(); renderPhotos(); });
  } else {
    const removed = state.photos.splice(it.legacyIndex, 1)[0];
    if (removed && removed.id && assetsApi) { try { assetsApi.delete(removed.id); } catch (e) {} }
    toast('Photo hata di');
  }
  persist(); renderPhotos(); renderBadges();
  if (!$('lightbox').classList.contains('hidden')) closeLb();
}

// ---------- Lightbox ----------
let lbItems = [], lbIndex = 0, lbStartX = null;
function openLb(i) {
  lbItems = getPhotoItems();
  if (!lbItems.length) return;
  lbIndex = Math.max(0, Math.min(i, lbItems.length - 1));
  $('lightbox').classList.remove('hidden');
  showLb();
}
function closeLb() {
  $('lightbox').classList.add('hidden');
  rerenderFlush(); renderPhotos();
}
function showLb() {
  const it = lbItems[lbIndex];
  if (!it) return closeLb();
  $('lbImg').src = it.src;
  const cap = $('lbCap');
  const ro = isReadOnly();
  cap.textContent = it.cap || (ro ? '' : 'Caption likho 💕');
  cap.contentEditable = ro ? 'false' : 'true';
  if (ro) {
    cap.onfocus = cap.oninput = cap.onblur = null;
  } else {
    cap.onfocus = () => { if (!state.caps[it.key]) cap.textContent = ''; };
    cap.oninput = () => { state.caps[it.key] = cap.innerText.trim(); persist(); };
    cap.onblur = () => {
      if (cap.innerText.trim()) return;
      cap.textContent = it.builtin ? (BUILTIN_CAPS[+it.key.slice(1)] || '') : 'Caption likho 💕';
    };
  }
  $('lbCount').textContent = `${lbIndex + 1} / ${lbItems.length}${ro ? ' · sirf dekhne ke liye' : ''}`;
  $('lbDel').classList.toggle('hidden', ro);
  $('lbDel').onclick = ro ? null : () => { if (confirm('Ye photo hatayein?')) { removeItem(it); } };
}
function step(d) {
  if (!lbItems.length) return;
  lbIndex = (lbIndex + d + lbItems.length) % lbItems.length;
  showLb();
}
$('lbPrev').addEventListener('click', () => step(-1));
$('lbNext').addEventListener('click', () => step(1));
$('lbClose').addEventListener('click', closeLb);
$('lightbox').addEventListener('pointerdown', e => { lbStartX = e.clientX; });
$('lightbox').addEventListener('pointerup', e => {
  if (lbStartX === null) return;
  const dx = e.clientX - lbStartX; lbStartX = null;
  if (Math.abs(dx) > 60) step(dx < 0 ? 1 : -1);
});
document.addEventListener('keydown', e => {
  if ($('lightbox').classList.contains('hidden')) return;
  if (e.key === 'ArrowLeft') step(-1);
  else if (e.key === 'ArrowRight') step(1);
  else if (e.key === 'Escape') closeLb();
});

// Re-render shared lists after an edit ends, if a live update arrived mid-edit
function rerenderFlush() {
  if (!rerenderLater) return;
  rerenderLater = false; renderNotes(); renderPhotos();
}

// ---------- Connect to shared storage ----------
async function connectShared() {
  if (!(window.claude && typeof window.claude.use === 'function')) return;
  try {
    const db = await window.claude.use('db');
    const assets = await window.claude.use('assets');
    const user = await window.claude.use('user');
    if (!db) return;
    usingDb = true;
    assetsApi = assets || null;
    dbDoc = db.doc('shared/state');
    if (user && typeof user.canEdit === 'function') {
      hasUserApi = true;
      try { canWrite = !!(await user.canEdit()); }
      catch (e) { hasUserApi = false; canWrite = true; } // permission API failed: fall back to PIN gate
    } else {
      canWrite = true;                                   // no permission API: PIN gate controls edits
    }

    dbDoc.onSnapshot(snap => {
      if (!snap.exists) {
        if (canWrite && (state.notes.length || state.photos.length || state.name)) flushSave();
        return;
      }
      if (snap.metadata.hasPendingWrites) return;
      const d = snap.data() || {};
      state = normalizeState({ name: d.name, notes: d.notes, photos: d.photos, caps: d.caps, hidden: d.hidden });
      persistLocal();
      if (document.activeElement && document.activeElement.isContentEditable) { rerenderLater = true; return; }
      nameInput.value = state.name || '';
      applyName(); renderNotes(); renderPhotos(); renderBadges();
    }, () => toast('Live update nahi aa raha, thodi der baad dekho'));

    applyName(); applyPermissions();
  } catch (e) { /* stay in local mode */ }
}

// ---------- Init ----------
applyName();
renderNotes();
renderPhotos();
renderStack();
renderBadges();
applyPermissions();
connectShared();

// ---------- Game 1: Catch the Hearts ----------
let cScore = 0, cLeft = 0, cTimers = [], cRun = false;
function endCatch() {
  cRun = false; cTimers.forEach(clearInterval); cTimers = []; $('catchArea').innerHTML = '';
  const msg = cScore >= 40 ? 'Champion! 🏆' : cScore >= 20 ? 'Nice reflexes! 💕' : 'Aur try karo! 💪';
  $('catchStatus').textContent = `Score ${cScore} · ${msg}`;
  $('catchStart').textContent = 'Phir se · Again'; $('catchStart').disabled = false;
  if (!flags.game) { flags.game = true; saveFlags(); renderBadges(); }
}
$('catchStart').addEventListener('click', () => {
  cScore = 0; cLeft = 15; cRun = true; $('catchStart').disabled = true;
  $('catchStatus').textContent = 'Score 0 · 15s';
  cTimers.push(setInterval(() => {
    const star = Math.random() < 0.2, el = document.createElement('button');
    el.className = 'falling'; el.textContent = star ? '⭐' : '💖';
    el.style.left = (Math.random() * 85) + '%';
    el.style.animationDuration = (2 + Math.random() * 1.5) + 's';
    el.addEventListener('click', e => {
      if (!cRun) return; cScore += star ? 5 : 1;
      $('catchStatus').textContent = `Score ${cScore} · ${cLeft}s`;
      confetti(e.clientX, e.clientY, 5); el.remove();
    });
    el.addEventListener('animationend', () => el.remove());
    $('catchArea').appendChild(el);
  }, 450));
  cTimers.push(setInterval(() => {
    cLeft--; $('catchStatus').textContent = `Score ${cScore} · ${cLeft}s`;
    if (cLeft <= 0) endCatch();
  }, 1000));
});

// ---------- Game 2: Memory ----------
const syms = ['🎸','🍕','⚽','🚀','🐶','🌮','🎮','🏆'];
let first = null, lock = false, matched = 0, moves = 0;
function startMem() {
  $('memGrid').innerHTML = ''; first = null; lock = false; matched = 0; moves = 0;
  $('memStatus').textContent = 'Moves: 0';
  [...syms, ...syms].sort(() => Math.random() - .5).forEach(s => {
    const c = document.createElement('button'); c.className = 'mcard'; c.dataset.s = s; c.textContent = '❔';
    c.addEventListener('click', () => flipMem(c)); $('memGrid').appendChild(c);
  });
}
function flipMem(c) {
  if (lock || c.textContent !== '❔') return;
  c.textContent = c.dataset.s;
  if (!first) { first = c; return; }
  moves++; $('memStatus').textContent = `Moves: ${moves}`;
  if (first.dataset.s === c.dataset.s) {
    first.classList.add('done'); c.classList.add('done'); matched++; first = null;
    if (matched === syms.length) {
      $('memStatus').textContent = `Wah! ${moves} moves mein jeet gaye 🎉`;
      if (!flags.game) { flags.game = true; saveFlags(); renderBadges(); }
    }
  } else {
    lock = true; const a = first, b = c;
    setTimeout(() => { a.textContent = '❔'; b.textContent = '❔'; first = null; lock = false; }, 700);
  }
}
$('memStart').addEventListener('click', startMem); startMem();

